import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { GpgUnlockPhase, GpgUnlockTarget } from '../types'
import {
  applyMasked,
  maskOf,
  parseGpgConfigKeys,
  parseKeygrip,
  parseKeyinfoCached,
  signingGitCommand,
} from './lib'

const PANE = 'gpg-unlock'
const LOCKED_STATUS = '🔒 GPG bloqueado · /gpg-unlock'

const masked = atom({ plugin: 'gpg-unlock', key: 'masked' } as const, 0)
const phase = atom({ plugin: 'gpg-unlock', key: 'phase' } as const, 'idle' as GpgUnlockPhase)
const message = atom({ plugin: 'gpg-unlock', key: 'message' } as const, '')
const target = atom({ plugin: 'gpg-unlock', key: 'target' } as const, null as GpgUnlockTarget | null)

type $ = EngineInterface

async function knownKeys($: $): Promise<Record<string, string>> {
  const home = await $.env.get('HOME')
  const script = await $.fs.read(`${home}/.local/bin/gpg-config`).catch(() => '')

  return parseGpgConfigKeys(typeof script === 'string' ? script : '')
}

/** `github` pelo gpg-config; sem nome, a user.signingkey do repo atual. */
async function resolveTarget($: $, name: string): Promise<GpgUnlockTarget | undefined> {
  const keys = await knownKeys($)
  const wanted = name.trim().toLowerCase()
  if (wanted !== '') {
    const key = keys[wanted]
    return key === undefined ? undefined : { label: wanted, key }
  }
  const ran = await $.process.run(['git', 'config', '--get', 'user.signingkey'])
  const key = ran.stdout.trim()
  if (ran.exitCode !== 0 || key === '') return undefined
  const label = Object.entries(keys).find(([, known]) => known === key)?.[0] ?? 'signingkey'

  return { label, key }
}

async function isCached($: $, key: string): Promise<boolean | undefined> {
  const listed = await $.process.run(['gpg', '--with-colons', '--with-keygrip', '-K', key])
  const grip = parseKeygrip(listed.stdout)
  if (grip === undefined) return undefined
  const info = await $.process.run(['gpg-connect-agent', `keyinfo ${grip}`, '/bye'])

  return parseKeyinfoCached(info.stdout)
}

async function signsCommits($: $): Promise<boolean> {
  const ran = await $.process.run(['git', 'config', '--get', 'commit.gpgsign'])

  return ran.stdout.trim() === 'true'
}

async function refreshStatus($: $): Promise<void> {
  if (!(await signsCommits($))) return $.ui.status(undefined)
  const t = await resolveTarget($, '')
  const cached = t === undefined ? undefined : await isCached($, t.key)
  $.ui.status(cached === false ? LOCKED_STATUS : undefined)
}

// Só a memória do módulo guarda a senha, e só até o Enter ou o cancelamento.
let secret = ''
let resumeAfterUnlock = false

async function forget($: $): Promise<void> {
  secret = ''
  await update($, masked, () => 0)
}

async function openPrompt($: $, t: GpgUnlockTarget, isAsked: boolean): Promise<void> {
  await forget($)
  await update($, target, () => t)
  await update($, phase, () => 'idle' as GpgUnlockPhase)
  await update($, message, () => '')
  await $.ui.open({ id: PANE, title: 'Desbloquear GPG', focus: isAsked ? true : undefined, closeOnEscape: true })
}

async function submit($: $): Promise<void> {
  const t = await read($, target)
  if (t === null) return
  if (secret === '') {
    await update($, message, () => 'Digite a senha antes do Enter.')
    return
  }
  const passphrase = secret
  await forget($)
  await update($, phase, () => 'checking' as GpgUnlockPhase)
  await update($, message, () => 'Conferindo com o gpg-agent…')

  const ran = await $.process.run(
    ['gpg', '--batch', '--yes', '--pinentry-mode', 'loopback', '--passphrase-fd', '0',
      '--local-user', t.key, '--detach-sign', '--output', '/dev/null', '/dev/null'],
    { stdin: `${passphrase}\n`, timeoutMs: 20_000 },
  ).catch((error: unknown) => ({ exitCode: -1, stderr: String(error), stdout: '' }))

  if (ran.exitCode !== 0) {
    const isWrong = /bad passphrase/i.test(ran.stderr)
    await update($, phase, () => (isWrong ? 'wrong' : 'error') as GpgUnlockPhase)
    const detail = ran.stderr.trim().split('\n').pop() ?? ''
    await update($, message, () => (isWrong ? 'Senha incorreta. Tente de novo.' : `Falhou: ${detail}`))
    return
  }

  await update($, phase, () => 'ok' as GpgUnlockPhase)
  await update($, message, () => '')
  $.ui.status(undefined)
  $.ui.toast(`🔓 Chave ${t.label} (${t.key}) desbloqueada no gpg-agent`)
  await $.ui.close({ id: PANE })
  if (resumeAfterUnlock) {
    resumeAfterUnlock = false
    await $.prompt.submit({
      text: 'O usuário desbloqueou a chave GPG pelo gpg-unlock. Repita o comando git assinado que foi bloqueado e continue a tarefa de onde parou.',
    })
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'gpg-unlock',
      description: 'Desbloqueia a chave GPG (como gpg-config unlock) digitando a senha num painel',
      argumentHint: '[github]',
    })
    void refreshStatus($).catch(() => undefined)
    $.clock.every(5 * 60_000, () => void refreshStatus($).catch(() => undefined))

    return next(e)
  })

  on('command.run', { command: 'gpg-unlock' }, async ($, e) => {
    const t = await resolveTarget($, e.args)
    if (t === undefined) {
      return { text: 'Não achei a chave: use /gpg-unlock github ou rode num repo com user.signingkey.' }
    }
    if ((await isCached($, t.key)) === true) {
      $.ui.status(undefined)
      return { text: `A chave ${t.label} (${t.key}) já está desbloqueada no gpg-agent.` }
    }
    await openPrompt($, t, true)

    return { text: `Digite a senha da chave ${t.label} no painel.` }
  })

  // Antes de um commit assinado: com a senha fora do cache, o pinentry travaria a sessão.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const kind = signingGitCommand(e.command)
    if (kind === undefined) return next(e)
    if (kind === 'commit' && !(await signsCommits($))) return next(e)
    const t = await resolveTarget($, '')
    if (t === undefined || (await isCached($, t.key)) !== false) return next(e)

    resumeAfterUnlock = true
    $.ui.status(LOCKED_STATUS)
    $.ui.toast(`🔒 Commit parado: a chave GPG ${t.label} está bloqueada. Rode /gpg-unlock`, { timeoutMs: 10_000 })
    await openPrompt($, t, false)

    return {
      deny: `gpg-unlock: a chave GPG ${t.label} (${t.key}) está bloqueada (a senha saiu do cache do gpg-agent), e este git ${kind} travaria esperando o pinentry. Já pedi a senha ao usuário pelo /gpg-unlock. Não repita o comando nem contorne a assinatura (nada de --no-gpg-sign): encerre o turno dizendo que está aguardando o desbloqueio do GPG. Quando ele desbloquear, chega uma mensagem pedindo para repetir o comando.`,
    }
  })

  on('ui.close', { id: PANE }, async ($, e, next) => {
    await forget($)

    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    if (e.surface === 'mobile') {
      const { Text } = $.ui.resolve(e)
      return <Text>Desbloqueie o GPG pelo terminal: /gpg-unlock</Text>
    }
    const { Box, Button, Input, Text } = $.ui.resolve(e)
    const t = await read($, target)
    const length = await read($, masked)
    const current = await read($, phase)
    const note = await read($, message)

    if (t === null) return <Text dimColor>Nada a desbloquear.</Text>

    return (
      <Box flexDirection="column" gap={1}>
        <Text>
          Chave <Text bold>{t.label}</Text> ({t.key})
        </Text>
        <Input
          key="passphrase"
          label="Senha: "
          value={maskOf(length)}
          placeholder="passphrase do GPG"
          submitLabel="desbloquear"
          autoFocus
          onInput={value => {
            secret = applyMasked(secret, value)
            void update($, masked, () => secret.length)
          }}
          onSubmit={value => {
            secret = applyMasked(secret, value)
            void submit($)
          }}
        />
        {note !== '' && (
          <Text color={current === 'checking' ? undefined : 'red'} dimColor={current === 'checking'}>
            {note}
          </Text>
        )}
        <Box gap={2}>
          <Button
            key="cancel"
            label="Cancelar"
            onPress={() => {
              void forget($)
              void $.ui.close({ id: PANE })
            }}
          />
          <Text dimColor>A senha vai direto ao gpg pelo stdin; não entra na conversa.</Text>
        </Box>
      </Box>
    )
  })
}

