// Lógica pura do gpg-unlock, separada para os testes.

const BULLET = '•'

/**
 * O campo mostra só bullets; cada edição chega como "•••x". Os bullets do
 * começo são o que já estava digitado; o resto é texto novo.
 */
export function applyMasked(secret: string, fieldValue: string): string {
  let kept = 0
  while (kept < fieldValue.length && fieldValue[kept] === BULLET) kept += 1

  return secret.slice(0, kept) + fieldValue.slice(kept)
}

export function maskOf(length: number): string {
  return BULLET.repeat(length)
}

/** Lê as chaves <NOME>_KEY (ex.: GITHUB_KEY) do script ~/.local/bin/gpg-config. */
export function parseGpgConfigKeys(script: string): Record<string, string> {
  const keys: Record<string, string> = {}
  for (const match of script.matchAll(/^([A-Z]+)_KEY="([0-9A-Fa-f]+)"/gm)) {
    const [, name, key] = match
    if (name !== undefined && key !== undefined) keys[name.toLowerCase()] = key
  }

  return keys
}

/** Keygrip da chave primária na saída de `gpg --with-colons --with-keygrip -K`. */
export function parseKeygrip(colons: string): string | undefined {
  let isAfterSec = false
  for (const line of colons.split('\n')) {
    const fields = line.split(':')
    if (fields[0] === 'sec') isAfterSec = true
    else if (isAfterSec && fields[0] === 'grp') return fields[9] || undefined
  }

  return undefined
}

/** `S KEYINFO <grip> D - - 1 P ...`: o 7º campo é "1" quando a senha está no cache. */
export function parseKeyinfoCached(output: string): boolean | undefined {
  const line = output.split('\n').find(one => one.startsWith('S KEYINFO '))
  if (line === undefined) return undefined

  return line.split(/\s+/)[6] === '1'
}

/**
 * Comandos git que assinam e travariam esperando o pinentry. Separa o comando
 * em trechos por ; && || | e olha cada `git ... commit` e `git tag -s`.
 */
export function signingGitCommand(command: string): 'commit' | 'tag' | undefined {
  for (const part of command.split(/;|&&|\|\||\||\n/)) {
    const words = part.trim().split(/\s+/)
    // git como comando do trecho, depois de VAR=valor opcionais.
    const gitAt = words.findIndex(word => !/^[A-Za-z_][A-Za-z0-9_]*=/.test(word))
    const head = words[gitAt] ?? ''
    if (head !== 'git' && !head.endsWith('/git')) continue
    const rest = words.slice(gitAt + 1)
    if (rest.includes('--no-gpg-sign')) continue
    const sub = rest.find((word, i) => !word.startsWith('-') && rest[i - 1] !== '-c' && rest[i - 1] !== '-C')
    if (sub === 'commit') return 'commit'
    if (sub === 'tag' && rest.some(word => word === '-s' || word === '--sign' || word.startsWith('-u'))) return 'tag'
  }

  return undefined
}

