export type GpgUnlockPhase = 'idle' | 'checking' | 'wrong' | 'ok' | 'error'

export type GpgUnlockTarget = { label: string; key: string }

declare module 'claude-code' {
  interface PluginState {
    'gpg-unlock': {
      /** Quantos caracteres a senha digitada tem (só o tamanho, nunca a senha). */
      masked: number
      phase: GpgUnlockPhase
      message: string
      target: GpgUnlockTarget | null
    }
  }
}
